/*data packet header*/
struct hgic_hdr {
    unsigned short magic;
    unsigned char  type;
    unsigned char  ifidx: 4, flags: 4;
    unsigned short length;
    unsigned short cookie;
} __packed;

struct hgic_frm_hdr {
    struct hgic_hdr hdr;
    union {
        struct hgic_rx_info rx_info;
        struct hgic_tx_info tx_info;
        unsigned char  rev[24];
    };
} __packed;

struct hgic_frm_hdr2 {
    struct hgic_hdr hdr;
} __packed;


/*contro pakcet header*/
struct hgic_ctrl_hdr {
    struct hgic_hdr hdr;
    union {
        struct {
            unsigned char  cmd_id;
            short status;
        } cmd;
        struct {
            unsigned short  cmd_id;
            short status;
        } cmd2;
        struct {
            unsigned char event_id;
            short value;
        } event;
        struct {
            unsigned short event_id;
            short value;
        } event2;
        struct {
            unsigned char  type;
        } hci;
        unsigned char info[4];
    };
} __packed;

struct hgic_exception_info {
    int num;
    union {
        struct  {
            int max, avg, min;
        } txdelay;
        struct  {
            int max, avg, min;
        } bgrssi;
        struct  {
            int total, used;
        } buffer_usage;
        struct  {
            int total, used;
        } heap_usage;
        struct  {
            int temp;
        } temperature;
    } info;
};

struct hgic_dhcp_result {
    unsigned int ipaddr, netmask, svrip, router, dns1, dns2;
};

