static void hgics_rx_bt_data(struct hgics_wdev *hg, u8 *data, int len)
{
#ifndef __RTOS__
    struct hgic_ctrl_hdr *hdr = (struct hgic_ctrl_hdr *)data;

    if ((u16)(hg->rx_cookie + 1) != hdr->hdr.cookie) {
        hgic_err("cookie:%d-%d\r\n", hg->rx_cookie, hdr->hdr.cookie);
    }
    hg->rx_cookie = hdr->hdr.cookie;

#ifdef CONFIG_BT
    if (hg->hci) {
		data += sizeof(struct hgic_ctrl_hdr);
		len  -= sizeof(struct hgic_ctrl_hdr);
        hci_recv_fragment(hg->hci, hdr->hci.type, data, len);
    } else
#endif
    {
        struct sk_buff *skb = dev_alloc_skb(len);
        if (skb) {
            memcpy(skb->data, data, len);
            skb_put(skb, len);
            if (skb_queue_len(&hg->evt_list) > 16) {
                kfree_skb(skb_dequeue(&hg->evt_list));
            }
            skb_queue_tail(&hg->evt_list, skb);
            up(&hg->evt_sema);
        } else {
            hgic_err("alloc skb fail, drop bt data ...\r\n");
        }
    }
#else
    /* TBD... */
#endif
}

void hgics_rx_error(void *hgobj)
{
    struct hgics_wdev *hg = hgobj;

    hgic_fwctrl_rx_error(&hg->ctrl);
}

int hgics_rx_data(void *hgobj, u8 *data, int len)
{
    int i = 0;
    struct hgics_wdev *hg = hgobj;
    struct hgic_frm_hdr *hdr = NULL;
    struct hgic_dack_hdr *ackhdr = NULL;
    struct hgics_txstatus txstat;
    u16 magic, declared;
    int actual = len;

    if (READ_ONCE(hg->bus->rx_failed))
        return -EPROTO;
    if (!data || len < sizeof(struct hgic_hdr))
        goto bad_rx;
    /* Retail alignment prefix is at most four0xff bytes; bound the
     * helper's otherwise unbounded lookahead before parsing any header.
     */
    for (i = 0; i < 4 && i < len && data[i] == 0xff; i++) {}
    if (len - i < sizeof(struct hgic_hdr))
        goto bad_rx;
    data += i; len -= i;
    hdr = (struct hgic_frm_hdr *)data;
    magic = get_unaligned_le16(data);
    declared = get_unaligned_le16(data + 4);
    /* Qualification policy: one exact CMD/CMD2 per original USB completion.
     * No RX padding/prefix grammar is established for station control. Do not
     * borrow TX alignment rules, trim surplus (even zero), or flatten packets.
     * All checks precede wire normalization and the asynchronous A1 decoder.
     */
    if (magic != HGIC_HDR_RX_MAGIC || declared < sizeof(struct hgic_hdr))
        goto bad_rx;
    if ((hdr->hdr.type == HGIC_HDR_TYPE_CMD || hdr->hdr.type == HGIC_HDR_TYPE_CMD2) &&
        (i != 0 || len < sizeof(struct hgic_ctrl_hdr) || declared != actual))
        goto bad_rx;
    if (hdr->hdr.type != HGIC_HDR_TYPE_BOOTDL && len < declared)
        goto bad_rx;
    hdr->hdr.magic  = le16_to_cpu(hdr->hdr.magic);
    hdr->hdr.length = le16_to_cpu(hdr->hdr.length);
    hdr->hdr.cookie = le16_to_cpu(hdr->hdr.cookie);

    if (hdr->hdr.magic != HGIC_HDR_RX_MAGIC) {
        hgic_err("invalid rx magic: %x\r\n", hdr->hdr.magic);
        return -1;
    }

    if (hdr->hdr.type != HGIC_HDR_TYPE_BOOTDL && len < hdr->hdr.length) {
        hgic_err("invalid data length: %x/%x, type:%d\r\n", len, hdr->hdr.length, hdr->hdr.type);
        return -1;
    }

    len = (len < hdr->hdr.length ? len : hdr->hdr.length);
    switch (hdr->hdr.type) {

        case HGIC_HDR_TYPE_SOFTFC:
            hg->last_rx = jiffies;
            atomic_set(&hg->txwnd, hdr->hdr.cookie);
            complete(&hg->txwnd_cp);
            break;
        case HGIC_HDR_TYPE_BLUETOOTH:
            if (!test_bit(HGICS_STATE_INITED, &hg->state) || hg->if_test) {
                return -1;
            }
            hgics_rx_bt_data(hg, data, len);
            break;
        default:
            hgic_err("unknow packet type:%d, len:%d, cookie:%x\n", hdr->hdr.type, len, hdr->hdr.cookie);
            return -1;
    }
    return 0;
bad_rx:
    hgics_rx_error(hg);
    return -EPROTO;
}

/* Caller holds lock. Poison all station waiters, not a later response chosen by
 * cookie alone. Boot/maintenance ownership is NOT qualified by this A1 change.
 */
static void hgic_fwctrl_bad_receipt(struct hgic_fwctrl *ctrl)
{
    struct hgic_cmd_response *resp;

    WRITE_ONCE(ctrl->receipt_error, -EPROTO);
    WRITE_ONCE(ctrl->bus->rx_failed, 1);
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if ((resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) && !resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
}

/* USB/core ingress uses the same locked A1 waiter/copy-admission latch. */
void hgic_fwctrl_rx_error(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;

    spin_lock_irqsave(&ctrl->lock, flags);
    hgic_fwctrl_bad_receipt(ctrl);
    spin_unlock_irqrestore(&ctrl->lock, flags);
}

static void hgic_fwctrl_work(struct work_struct *work)
{
    struct hgic_fwctrl *ctrl = NULL;
    struct sk_buff *skb = NULL;
    struct hgic_ctrl_hdr *hdr = NULL;

    ctrl = container_of(work, struct hgic_fwctrl, work);
    while (!skb_queue_empty(&ctrl->rxq)) {
        skb = skb_dequeue(&ctrl->rxq);
        if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
            hgic_fwctrl_rx_response(ctrl, skb);
            continue;
        }
        hdr = (struct hgic_ctrl_hdr *)skb->data;
        switch (hdr->hdr.type) {
            case HGIC_HDR_TYPE_CMD:
            case HGIC_HDR_TYPE_CMD2:
            case HGIC_HDR_TYPE_BOOTDL:
            case HGIC_HDR_TYPE_OTA:
                hgic_fwctrl_rx_response(ctrl, skb);
                break;
            case HGIC_HDR_TYPE_EVENT:
            case HGIC_HDR_TYPE_EVENT2:
                ctrl->rx_event(ctrl, skb);
                break;
            default:
                hgic_fwctrl_rx_response(ctrl, skb);
                break;
        }
    }
}

void hgic_fwctrl_rx(struct hgic_fwctrl *ctrl, u8 *data, int len)
{
    struct sk_buff *skb;
    unsigned long flags;
    if (!data || len <= 0 || len > 0xffff) {
        spin_lock_irqsave(&ctrl->lock, flags);
        hgic_fwctrl_bad_receipt(ctrl);
        spin_unlock_irqrestore(&ctrl->lock, flags);
        return;
    }
    if (ctrl->wq) {
        skb = dev_alloc_skb(len);
        if (skb) {
            memcpy(skb->data, data, len);
            skb_put(skb, len);
            skb_queue_tail(&ctrl->rxq, skb);
            queue_work(ctrl->wq, &ctrl->work);
        } else {
            hgic_err("alloc skb fail\r\n");
        }
    } else {
        hgic_err("fwctrl workqueue is NULL\r\n");
    }
}

void hgic_fwctrl_init(struct hgic_fwctrl *ctrl, void *dev, struct hgic_bus *bus)
{
    memset(ctrl, 0, sizeof(struct hgic_fwctrl));
    ctrl->dev = dev;
    ctrl->bus = bus;
    ctrl->radio_onoff = 1;
    spin_lock_init(&ctrl->lock);
    INIT_LIST_HEAD(&ctrl->pd_list);
    skb_queue_head_init(&ctrl->rxq);
    skb_queue_head_init(&ctrl->txq);
    INIT_WORK(&ctrl->work, hgic_fwctrl_work);
    ctrl->wq = ALLOC_ORDERED_WORKQUEUE("fwctrl", 0);
}

