static_assert(sizeof(struct hgic_ctrl_hdr) == 12, "selected control ABI");
static_assert(offsetof(struct hgic_ctrl_hdr, cmd.status) == 10, "selected CMD status");
static_assert(offsetof(struct hgic_ctrl_hdr, cmd2.status) == 10, "selected CMD2 status");

/* rx.c normalizes these three outer u16 fields to CPU endian before fwctrl_rx.
 * The remaining command/status/payload fields are still little endian.
 * Do not reinterpret the mirror's 28-byte fw_info as a retail wire object.
 */
static inline bool hgic_ctrl_frame_valid(const u8 *data, size_t len)
{
    return data && len >= sizeof(struct hgic_ctrl_hdr) && len <= 0xffff &&
           get_unaligned((const u16 *)(data + 0)) == HGIC_HDR_RX_MAGIC &&
           get_unaligned((const u16 *)(data + 4)) == len;
}

static void hgic_usb_receive(struct urb *urb)
{
    struct hgic_usb_buf *buf = (struct hgic_usb_buf *)urb->context;
    struct hgic_usb *usbdev = buf->usbdev;
    int ret;

    //hgic_enter();
    if (buf->usbdev->status & HGIC_USB_STATUS_STOP) {
        hgic_usb_enq(buf, &buf->usbdev->rx_freeq);
        hgic_err("STOP, drop data, status=%x\r\n", buf->usbdev->status);
        return;
    }

    /* STOP is normal cancellation above: never deliver or resubmit it. Other
     * completion failures poison A1 acceptance, including error+zero. A successful
     * zero-length completion has no established station wire meaning: reject.
     * The allocated backing is exactly max_pkt_len; verify the URB still names
     * that backing and its full extent before trusting actual_length or data.
     */
    if ((usbdev->status & HGIC_USB_STATUS_ERR) || READ_ONCE(usbdev->bus.rx_failed) ||
        urb->status || !buf->data || urb->transfer_buffer != buf->data ||
        urb->transfer_buffer_length != max_pkt_len ||
        urb->actual_length <= 0 || urb->actual_length > urb->transfer_buffer_length)
        goto bad_rx;
    ret = usbdev->bus.rx_packet(usbdev->bus.bus_priv, buf->data, urb->actual_length);
    if (ret == -EPROTO || READ_ONCE(usbdev->bus.rx_failed))
        goto bad_rx;
    hgic_usb_submit_rx_urb(buf);
    //hgic_leave();
    return;
bad_rx:
    usbdev->status |= HGIC_USB_STATUS_ERR;
    WRITE_ONCE(usbdev->bus.rx_failed, 1);
    if (usbdev->bus.rx_error)
        usbdev->bus.rx_error(usbdev->bus.bus_priv);
    /* Keep backing owned. Other in-flight URBs retire through their callbacks;
     * this is not a kill/drain/free or a global work-cancellation receipt.
     */
    hgic_usb_enq(buf, &usbdev->rx_freeq);
}

static void hgics_detect_work(struct work_struct *work)
{
    int status = -1;
    struct hgics_wdev *hg  = container_of(work, struct hgics_wdev, detect_work);

    if (!test_bit(HGIC_BUS_FLAGS_SLEEP, &hg->bus->flags) && !test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        if (test_bit(HGIC_BUS_FLAGS_ERROR, &hg->bus->flags) || time_after(jiffies, hg->last_rx + msecs_to_jiffies(HGIC_DETECT_TIMER))) {
            status = hgic_bootdl_cmd_enter(&hg->bootdl);
            if (status != STATE_FW) {
                hg->soft_fc = 0;
                clear_bit(HGICS_STATE_START, &hg->state);
                hgic_clear_queue(&hg->ctrl.txq);
                if(hg->bus->reinit){
                    hg->bus->reinit(hg->bus);
                }
                if (!test_bit(HGICS_STATE_REMOVE, &hg->state)) {
                    schedule_work(&hg->delay_init);
                }
            }
        }
    }

    if (!test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        mod_timer(&hg->detect_tmr, jiffies + msecs_to_jiffies(HGIC_DETECT_TIMER));
    }
}

